
CREATE TABLE "all_types" (
  "id" NUMBER(10) NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" VARCHAR2(255) NOT NULL,
  "full" CLOB NOT NULL,
  "price" NUMBER(16, 2) NOT NULL,
  "big_p" NUMBER(20, 6) NOT NULL,
  "flag" NUMBER(1) NOT NULL,
  "data" BLOB NOT NULL,
  "meta" CLOB NOT NULL,
  "created" TIMESTAMP NOT NULL,
  "born" DATE NOT NULL,
  "code" VARCHAR2(64) NOT NULL,
  "ver" NUMBER(19) NOT NULL,
  "amt" NUMBER(10, 2) NOT NULL,
  "cnt" NUMBER(10) NOT NULL
);
